// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AuthorizeCli Issue a one-time code that a cli exchanges for its own session
	// (POST /auth/cli/authorize)
	AuthorizeCli(ctx context.Context, request AuthorizeCliRequestObject) (AuthorizeCliResponseObject, error)
	// ExchangeCliCode Exchange a cli authorization code and PKCE verifier for a session
	// (POST /auth/cli/token)
	ExchangeCliCode(ctx context.Context, request ExchangeCliCodeRequestObject) (ExchangeCliCodeResponseObject, error)
	// DevLogin Log in as a dev user without a password (DEBUG only)
	// (POST /auth/dev-login)
	DevLogin(ctx context.Context, request DevLoginRequestObject) (DevLoginResponseObject, error)
	// ListDevUsers List dev user emails (DEBUG only)
	// (GET /auth/dev-users)
	ListDevUsers(ctx context.Context, request ListDevUsersRequestObject) (ListDevUsersResponseObject, error)
	// Login Log in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Refresh Exchange a refresh token for a new token pair
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Signup Create an account with email and password
	// (POST /auth/signup)
	Signup(ctx context.Context, request SignupRequestObject) (SignupResponseObject, error)
	// ListDevices List the authenticated user's devices, newest first
	// (GET /devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// CreateDeviceRegistrationCode Issue a one-time code that registers a device to the authenticated user
	// (POST /devices/registration-codes)
	CreateDeviceRegistrationCode(ctx context.Context, request CreateDeviceRegistrationCodeRequestObject) (CreateDeviceRegistrationCodeResponseObject, error)
	// GetDevice Get one of the authenticated user's devices
	// (GET /devices/{id})
	GetDevice(ctx context.Context, request GetDeviceRequestObject) (GetDeviceResponseObject, error)
	// UpdateDevice Update one of the authenticated user's devices
	// (PATCH /devices/{id})
	UpdateDevice(ctx context.Context, request UpdateDeviceRequestObject) (UpdateDeviceResponseObject, error)
	// GetMe Get the authenticated user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// AuthorizeCli operation middleware
func (sh *strictHandler) AuthorizeCli(w http.ResponseWriter, r *http.Request) {
	var request AuthorizeCliRequestObject

	var body AuthorizeCliJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.AuthorizeCli(ctx, request.(AuthorizeCliRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "AuthorizeCli")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(AuthorizeCliResponseObject); ok {
		if err := validResponse.VisitAuthorizeCliResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

